def parse_student(line):
    fields = line.rstrip("\n").split(",")
    if len(fields) != 3:
        raise ValueError("record must contain id, name and mark")

    student_id, name, mark_text = fields
    mark = int(mark_text)
    if not 0 <= mark <= 100:
        raise ValueError("mark is outside 0 to 100")

    return {"id": student_id, "name": name, "mark": mark}

