def find_student(filename, target_id):
    with open(filename, "r", encoding="utf-8") as file:
        for line in file:
            student = parse_student(line)
            if student["id"] == target_id:
                return student
            if student["id"] > target_id:
                break  # later keys will be even larger
    return None

def load_marks(filename):
    marks = []
    try:
        with open(filename, "r", encoding="utf-8") as file:
            for line_number, line in enumerate(file, start=1):
                marks.append(int(line.strip()))
    except FileNotFoundError:
        print(f"Cannot open {filename}: file not found")
        return None
    except ValueError:
        print(f"Invalid integer on line {line_number}")
        return None
    else:
        return marks

def average(filename):
    file = None
    try:
        file = open(filename, "r", encoding="utf-8")
        values = [int(line) for line in file]
        return sum(values) / len(values)
    except FileNotFoundError:
        print("File not found")
    except ZeroDivisionError:
        print("File is empty: cannot average")
    finally:
        if file is not None:
            file.close()
            print("closed")
    return None

